     9  #include <stdint.h>  // uint16_t, uint32_t
    10
    11  // The high surrogate may be uninitialized if the pair is invalid,
    12  // we choose to ignore the problem to reduce the size of the code
    13  // Garbage in => Garbage out
    14  #if defined(__GNUC__)
    15  #if __GNUC__ >= 7
    16  #pragma GCC diagnostic push
    17  #pragma GCC diagnostic ignored "-Wmaybe-uninitialized"
    18  #endif
    19  #endif
    20
    21  namespace ARDUINOJSON_NAMESPACE {
    22
    23  namespace Utf16 {
    24  inline bool isHighSurrogate(uint16_t codeunit) {
    25    return codeunit >= 0xD800 && codeunit < 0xDC00;
    26  }
    27
    28  inline bool isLowSurrogate(uint16_t codeunit) {
    29    return codeunit >= 0xDC00 && codeunit < 0xE000;
    30  }
    31
    32  class Codepoint {
    33   public:
    34    bool append(uint16_t codeunit) {
    35      if (isHighSurrogate(codeunit)) {
    36        _highSurrogate = codeunit & 0x3FF;
    37        return false;
    38      }
    39
    40      if (isLowSurrogate(codeunit)) {
    41        _codepoint =
    42            uint32_t(0x10000 + ((_highSurrogate << 10) | (codeunit & 0x3FF)));
    43        return true;
    44      }
    45
    46      _codepoint = codeunit;
    47      return true;
    48    }
    49
    50    uint32_t value() const {
    51      return _codepoint;
    52    }
    53
    54   private:
    55    uint16_t _highSurrogate;
    56    uint32_t _codepoint;
    57  };
    58  }  // namespace Utf16
    59  }  // namespace ARDUINOJSON_NAMESPACE
    60
